/* Cohesive world-space materials. Seeded texture tiles never change on repaint. */
function studioPattern(base,kind,seed){const n=192,[c,x]=mk(n,n),r=rng(seed);x.fillStyle=base;x.fillRect(0,0,n,n);
 // Large, very subtle patches under the fine material detail.
 for(let i=0;i<28;i++){const px=r()*n,py=r()*n,rr=8+r()*30,g=x.createRadialGradient(px,py,0,px,py,rr);g.addColorStop(0,i%2?'rgba(255,241,195,.012)':'rgba(39,52,28,.01)');g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(px-rr,py-rr,rr*2,rr*2)}
 if(kind==='grass'||kind==='moss')for(let i=0;i<620;i++){const px=r()*n,py=r()*n;x.strokeStyle=i%3?'rgba(62,92,40,.19)':'rgba(239,238,185,.35)';x.lineWidth=.6;x.beginPath();x.moveTo(px,py);x.lineTo(px+(r()-.5)*3,py-1-r()*3);x.stroke()}
 if(kind==='soil'||kind==='gravel'||kind==='sand'||kind==='snow')for(let i=0;i<(kind==='gravel'?1800:800);i++){x.fillStyle=i%3?'rgba(62,47,30,.12)':'rgba(255,243,216,.3)';x.beginPath();x.ellipse(r()*n,r()*n,kind==='gravel'?.6+r()*1.2:.2+r()*.65,.3+r()*.6,r()*3,0,7);x.fill()}
 if(kind==='stone')for(let y=-6;y<n+8;y+=8)for(let px=-8+(Math.floor(y/8)%2)*6;px<n+10;px+=12){const z=r();x.fillStyle=shade(base,(z-.45)*.17);x.beginPath();x.roundRect(px+.6,y+.7,10.7,6.7,1.5);x.fill();x.strokeStyle='rgba(48,49,42,.28)';x.lineWidth=.6;x.stroke();x.strokeStyle='rgba(255,244,212,.2)';x.beginPath();x.moveTo(px+1.7,y+1.3);x.lineTo(px+9,y+1.3);x.stroke()}
 if(kind==='slab')for(let y=0;y<n;y+=24)for(let px=(y/24%2)*-16;px<n;px+=32){x.fillStyle=shade(base,(r()-.4)*.15);x.fillRect(px+1,y+1,30,22);x.strokeStyle='rgba(30,35,32,.28)';x.lineWidth=1;x.strokeRect(px+.5,y+.5,31,23);if(r()>.6){x.beginPath();x.moveTo(px+8,y+1);x.lineTo(px+12,y+9);x.lineTo(px+11,y+15);x.stroke()}}
 if(kind==='wood')for(let y=0;y<n;y+=9){x.fillStyle=shade(base,(r()-.5)*.18);x.fillRect(0,y,n,8);x.fillStyle='rgba(53,34,20,.3)';x.fillRect(0,y+8,n,1);const seam=r()*n;x.fillRect(seam,y,1,8);x.strokeStyle='rgba(239,208,151,.14)';x.lineWidth=.6;for(let j=0;j<3;j++){x.beginPath();x.moveTo(0,y+2+j*2);x.bezierCurveTo(50,y+j*2,90,y+4+j,n,y+2+j*2);x.stroke()}for(const px of[seam+3,seam-3])circ(x,px,y+2.5,.55,'#53432d')}
 if(kind==='ice'){x.strokeStyle='rgba(228,252,255,.5)';x.lineWidth=.7;for(let i=0;i<22;i++){let px=r()*n,py=r()*n;x.beginPath();x.moveTo(px,py);for(let j=0;j<3;j++){px+=(r()-.5)*35;py+=r()*18;x.lineTo(px,py)}x.stroke()}}
 return ctx.createPattern(c,'repeat')
}
