$('tools').after(library);
const libToggle=document.createElement('button');libToggle.id='libraryToggle';libToggle.className='hbtn on';libToggle.innerHTML=ico('library');libToggle.title='Библиотека';libToggle.setAttribute('aria-label','Библиотека');document.querySelector('header').insertBefore(libToggle,$('undo'));
