function toggleLibrary(force){studio.open=force===undefined?!studio.open:force;const small=innerWidth<=800;$('app').classList.toggle('libraryClosed',!studio.open&&!small);library.classList.toggle('open',studio.open&&small);libToggle.classList.toggle('on',studio.open);libToggle.setAttribute('aria-expanded',String(studio.open));requestAnimationFrame(()=>{resize()})}
libToggle.onclick=()=>{if(innerWidth<=1100)$('panel').classList.remove('open');toggleLibrary()};$('libClose').onclick=()=>toggleLibrary(false);$('libHelp').onclick=()=>help.showModal();
motionBtn.onclick=()=>{state.motion=state.motion===false;commit();syncStudio();if(studio.inspector==='scene')renderPanel()};
const panelToggleOriginal=$('panelToggle').onclick;$('panelToggle').onclick=()=>{if(innerWidth<=800)toggleLibrary(false);panelToggleOriginal()};
function syncStudio(){motionBtn.innerHTML=ico(state.motion===false?'play':'pause');motionBtn.title=state.motion===false?'Включить анимации':'Пауза анимации';motionBtn.setAttribute('aria-label',motionBtn.title);motionBtn.classList.toggle('on',state.motion===false)}
function setLibraryCategory(cat){if(!CAT[cat])return;studio.category=cat;studio.query='';$('librarySearch').value='';toggleLibrary(true);renderLibrary();renderTools()}
function renderTools(){const items=['terrain','roads','buildings','nature','props','interior','effects'];$('tools').innerHTML=`<button class="tool${tool==='select'?' on':''}" data-t="select" title="Выбор · V" aria-label="Выбор">${ico('cursor')}</button><button class="tool${tool==='hand'?' on':''}" data-t="hand" title="Перемещение · H" aria-label="Перемещение">${ico('hand')}</button><div class="tgap"></div>${items.map(k=>`<button class="tool${studio.category===k?' activeCat':''}" data-category="${k}" title="${CAT[k].name}" aria-label="${CAT[k].name}" aria-pressed="${studio.category===k}">${ico(CAT[k].icon)}</button>`).join('')}<div class="railFoot"><button class="tool${tool==='measure'?' on':''}" data-t="measure" title="Измерить · I" aria-label="Измерить расстояние">${ico('ruler')}</button><button class="tool${studio.category==='favorites'?' activeCat':''}" data-category="favorites" title="Избранное" aria-label="Избранное">${ico('star')}</button><button class="tool${tool==='erase'?' on':''}" data-t="erase" title="Ластик · X" aria-label="Ластик">${I('<path d="m4 14 9-9 5 5-7 7H7zM10 17h8"/>')}</button></div>`}
$('tools').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b)setLibraryCategory(b.dataset.category)});
function filteredAssets(){const q=studio.query.trim().toLocaleLowerCase('ru');return CATALOG.filter(a=>q?(a.name+' '+a.tags+' '+CAT[a.cat].name).toLocaleLowerCase('ru').includes(q):studio.category==='favorites'?studio.favorites.has(a.id):studio.category==='recent'?studio.recent.includes(a.id):a.cat===studio.category).sort((a,b)=>studio.category==='recent'&&!q?studio.recent.indexOf(a.id)-studio.recent.indexOf(b.id):0)}
const thumbCache=new Map();
function thumbnail(a){if(thumbCache.has(a.id))return thumbCache.get(a.id);const[c,x]=mk(192,132);x.translate(96,66);x.scale(2.1,2.1);x.save();
 if(a.kind==='material'){x.rotate(-.1);x.fillStyle=MATS[a.mat].p;x.beginPath();x.roundRect(-31,-23,62,46,5);x.fill();x.strokeStyle='#ffffff80';x.lineWidth=1;x.stroke()}
 else if(a.kind==='stamp')drawStamp(x,{type:a.stamp,x:0,y:0,s:1,rot:0,v:31},0,true);
 else if(a.kind==='tree')drawTree(x,{x:0,y:0,r:20,v:31,type:a.species},0,true);
 else if(a.kind==='road'){drawRoad(x,{pts:[[-33,18],[-12,8],[12,-8],[33,-16]],w:15,mat:a.road},true)}
 else if(a.kind==='building'||a.kind==='kit'||a.kind==='district'){const S=sx[a.style]||sx.medieval;const roof=a.kind==='building'?S.roof:'gable';if(a.kind==='district'){for(const[px,py]of[[-15,-10],[15,-9],[-15,14],[15,15]])drawBuilding(x,{kind:'house',pts:rectPts(px,py,22,15,0),h:18,color:S.colors[0],roof,style:'medieval',floors:2},true)}else drawBuilding(x,{kind:a.tool==='tower'?'tower':'house',pts:a.tool==='tower'?ovalPts(0,0,23,23):rectPts(0,0,49,35,-.1),h:24,color:S.colors[0],roof,style:a.style||'medieval',floors:2,chimney:true},true)}
 else if(a.kind==='land'){if(a.tool==='river'){drawRiver(x,{pts:[[-32,20],[0,-10],[32,-15]],w:14,bank:a.params.bank},0,true)}else if(a.tool==='water'){x.fillStyle='#4f919c';x.beginPath();x.ellipse(0,0,32,20,-.2,0,7);x.fill();x.strokeStyle='#d9c39a';x.lineWidth=4;x.stroke()}else{for(let i=0;i<(a.params.hillLvl===2?2:1);i++){x.fillStyle='#76674b';x.beginPath();x.ellipse(0,5-i*9,32-i*10,19-i*5,-.15,0,7);x.fill();x.fillStyle='#9bb477';x.beginPath();x.ellipse(-2,-i*9,31-i*10,18-i*5,-.15,0,7);x.fill()}}}
 else if(a.kind==='wall'){drawWall(x,{pts:[[-30,12],[30,-10]],t:8,style:a.params.wallStyle||'stone',h:12},true)}
 else{x.fillStyle='#415e49';x.font='italic 22px Georgia';x.textAlign='center';x.fillText('Aa',0,7)}
 x.restore();const url=c.toDataURL('image/png');thumbCache.set(a.id,url);return url}
function renderLibrary(){const catSelect=$('libCategory');catSelect.innerHTML=Object.entries(CAT).map(([k,v])=>`<option value="${k}"${studio.category===k?' selected':''}>${v.name}${k==='favorites'?' · '+studio.favorites.size:''}</option>`).join('');renderCards()}
function renderCards(){const items=filteredAssets();$('libMeta').innerHTML=`<span>${studio.query?'Найдено':'Всего'}: ${items.length}</span>${studio.query?'<button id="clearSearch">Сбросить</button>':'<span>Выбери → поставь</span>'}`;$('assetGrid').innerHTML=items.length?items.map(a=>`<div class="assetCard${studio.asset===a.id?' active':''}"><button class="assetBody" data-asset="${esc(a.id)}" title="${esc(a.name)}" aria-pressed="${studio.asset===a.id}"><img class="assetPreview" src="${thumbnail(a)}" alt="" draggable="false"><span class="assetLabel">${esc(a.name)}</span></button><button class="assetFavorite${studio.favorites.has(a.id)?' isFav':''}" data-favorite="${esc(a.id)}" aria-label="${studio.favorites.has(a.id)?'Убрать из избранного':'В избранное'}: ${esc(a.name)}" aria-pressed="${studio.favorites.has(a.id)}">${ico('star')}</button>${a.animated?`<span class="assetAnimated" title="Анимированный объект">${ico('play')}</span>`:''}</div>`).join(''):'<div class="libEmpty"><b>Здесь пока пусто</b>Попробуй другой запрос или добавь предметы в избранное звёздочкой.</div>'}
function useAsset(id){const a=CATALOG.find(a=>a.id===id);if(!a)return;if(studio.asset!==id)opts.scatterEnabled=false;studio.asset=id;Object.assign(opts,a.params);studio.inspector='properties';studio.recent=[id,...studio.recent.filter(k=>k!==id)].slice(0,16);libraryPersist();setTool(a.tool);renderLibrary();if(innerWidth<=800)toggleLibrary(false);$('hint').innerHTML=`<b>${esc(a.name)}.</b> ${a.tool==='stamp'?'Нажми на карту. Размер, поворот и кисть — в параметрах.':TOOLS.find(t=>t.id===a.tool)?.h||''}`}
$('librarySearch').addEventListener('input',e=>{studio.query=e.target.value;renderCards()});$('libCategory').onchange=e=>setLibraryCategory(e.target.value);
library.addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){const id=f.dataset.favorite;studio.favorites.has(id)?studio.favorites.delete(id):studio.favorites.add(id);libraryPersist();renderCards();return}const a=e.target.closest('[data-asset]');if(a)useAsset(a.dataset.asset);if(e.target.closest('#clearSearch')){studio.query='';$('librarySearch').value='';renderCards();$('librarySearch').focus()}});
window.addEventListener('keydown',e=>{if(e.key==='/'&&!e.metaKey&&!e.ctrlKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!help.open){e.preventDefault();toggleLibrary(true);$('librarySearch').focus()}if(e.key==='Escape'&&document.activeElement===$('librarySearch')){studio.query='';$('librarySearch').value='';$('librarySearch').blur();renderCards()}});

/* Detailed rendering: all graphics are original editable procedural assets. */
const treeSprites=new Map(),objectSprites=new Map();
const tree02=drawTree,stamp02=drawStamp,building02=drawBuilding,wall02=drawWall,river02=drawRiver,label02=drawLabel;
function leafSprite(t){const key=[t.type||'oak',t.v,t.r,t.autumn,Math.round(state.light/10)].join(':');if(treeSprites.has(key))return treeSprites.get(key);const r=rng(t.v),R=t.r,[c,x]=mk(Math.ceil(R*5+16),Math.ceil(R*5+16)),cx=c.width/2,cy=c.height/2;x.translate(cx,cy);x.scale(2,2);const type=t.type||'oak';
 if(type==='dead'){x.strokeStyle='#75664c';x.lineWidth=2.2;x.lineCap='round';for(let i=0;i<8;i++){const a=i/8*6.28+r()*.3,dx=Math.cos(a),dy=Math.sin(a),len=R*(.6+r()*.35);x.beginPath();x.moveTo(0,0);x.lineTo(dx*len,dy*len);x.lineTo(dx*(len+3)-dy*3,dy*(len+3)+dx*3);x.moveTo(dx*len*.6,dy*len*.6);x.lineTo(dx*len*.8+dy*5,dy*len*.8-dx*5);x.stroke()}circ(x,0,0,2.4,'#8f7f5e')}
 else if(type==='pine'){for(let layer=0;layer<4;layer++){const radius=R*(1-layer*.19),pts=Array.from({length:24},(_,i)=>{const a=i/24*6.28,z=radius*(i%2?.72:1);return[Math.cos(a)*z,Math.sin(a)*z]});poly(x,pts,['#324f3d','#3d6144','#527748','#6e8b54'][layer],'#233d2c',.65);x.translate(-.6,-.8)}for(let i=0;i<40;i++){const a=r()*6.28,d=r()*R*.8;circ(x,Math.cos(a)*d,Math.sin(a)*d,.3+r()*.6,'rgba(205,218,150,.22)')}}
 else{const base=t.autumn?['#b28142','#b36938','#a78f44'][t.v%3]:type==='willow'?'#729166':['#688651','#587d4d','#7c945c','#4f744b'][t.v%4];const lobes=[];for(let i=0;i<7;i++){const a=i/7*6.28+r()*.2,d=R*.48;lobes.push([Math.cos(a)*d,Math.sin(a)*d,R*(.48+r()*.12)])}lobes.push([-R*.12,-R*.12,R*.65]);for(const[px,py,rr]of lobes){const g=x.createRadialGradient(px-rr*.3,py-rr*.4,1,px,py,rr);g.addColorStop(0,shade(base,.18));g.addColorStop(.7,base);g.addColorStop(1,shade(base,-.18));circ(x,px,py,rr,g,shade(base,-.3),.55)}x.save();const pts=Array.from({length:24},(_,i)=>{const a=i/24*6.28;return[Math.cos(a)*R*.96,Math.sin(a)*R*.96]});tracePath(x,pts,true);x.clip();for(let i=0;i<180;i++){const px=(r()-.5)*R*2,py=(r()-.5)*R*2;x.fillStyle=i%3?shade(base,-.12):shade(base,.28);x.globalAlpha=.45;x.beginPath();x.ellipse(px,py,.6+r()*1.1,.3+r()*.7,r()*3,0,7);x.fill()}x.globalAlpha=1;if(type==='willow'){x.strokeStyle=shade(base,.25);x.lineWidth=.7;for(let i=0;i<14;i++){const a=i/14*6.28;x.beginPath();x.moveTo(Math.cos(a)*R*.3,Math.sin(a)*R*.3);x.quadraticCurveTo(Math.cos(a+.1)*R*.7,Math.sin(a+.1)*R*.7+2,Math.cos(a)*R,Math.sin(a)*R+4);x.stroke()}}x.restore()}
 if(treeSprites.size>700)treeSprites.clear();const out={c,w:c.width/2,h:c.height/2};treeSprites.set(key,out);return out
}
drawTree=function(c,t,time=0,force=false){if(!force&&!layerVisible('nature'))return;const s=leafSprite(t),tt=force?0:motionTime(time),sw=Math.sin(tt*.9+t.v*.01)*(state.wind??.5)*.8;c.drawImage(s.c,t.x-s.w/2+sw,t.y-s.h/2,s.w,s.h)};
const addTree02=addTree;addTree=function(x,y,r,autumn){addTree02(x,y,r,autumn);state.trees[state.trees.length-1].type=opts.treeType||'oak'};

drawRoad=function(c,r,force=false){if(!force&&!layerVisible('roads'))return;const type=r.mat&&ROADMATS[r.mat]?r.mat:r.paved?'cobble':'dirt',M=ROADMATS[type],p=sm(r);c.save();c.lineCap=c.lineJoin='round';tracePath(c,p);c.strokeStyle=type==='boardwalk'?'#4e4835':'rgba(92,78,49,.4)';c.lineWidth=r.w+5;c.stroke();c.strokeStyle=type==='boardwalk'?'#b79968':shade(MATS[M.mat].c,-.12);c.lineWidth=r.w+2;c.stroke();c.strokeStyle=MATS[M.mat].p;c.lineWidth=r.w;c.stroke();if(type==='dirt'||type==='trail'){c.strokeStyle='rgba(238,215,166,.22)';c.lineWidth=r.w*.48;c.stroke();if(type==='dirt'){c.strokeStyle='rgba(117,88,47,.22)';c.lineWidth=1.2;for(const k of[-.28,.28]){tracePath(c,offsetLine(p,r.w*k));c.stroke()}}}if(type==='cobble'||type==='slab'){c.strokeStyle='rgba(235,224,195,.4)';c.lineWidth=.8;for(const k of[-.48,.48]){tracePath(c,offsetLine(p,r.w*k));c.stroke()}}if(type==='boardwalk'){walk(p,7,(x,y,a)=>{c.save();c.translate(x,y);c.rotate(a);c.strokeStyle='#564831';c.lineWidth=.75;c.beginPath();c.moveTo(0,-r.w/2);c.lineTo(0,r.w/2);c.stroke();for(const y of[-r.w/2+2,r.w/2-2])circ(c,0,y,.65,'#65553b');c.restore()})}c.restore()};
