renderPanel=function(){panel02();const p=$('panel'),o=findSel(),sections=[...p.children],mapSec=p.querySelector('#g-light')?.closest('section'),exportSec=p.querySelector('#exPng')?.closest('section');
 if(studio.inspector==='scene'){p.innerHTML='<section><p class="ptitle">Атмосфера и карта</p><p class="pdesc">Настроение сцены, масштаб и экспорт.</p>'+selectField('scene-weather','Погода',[['clear','Ясно'],['fog','Туман'],['rain','Дождь'],['snow','Снег']],state.weather||'clear')+field('scene-weatherAmount','Интенсивность',0,1,state.weatherAmount??.45,.05)+field('scene-wind','Ветер',0,1,state.wind??.5,.05)+`<label class="check"><input id="scene-motion" type="checkbox"${state.motion!==false?' checked':''}> Анимации сцены</label><p class="smallnote">Пауза останавливает воду, листву, объекты и осадки. При системном уменьшении движения анимации отключены.</p></section>`;if(mapSec)p.append(mapSec);if(exportSec)p.append(exportSec);p.insertAdjacentHTML('beforeend','<section><div class="row2"><button class="pbtn" id="scene-undo">Отменить</button><button class="pbtn" id="scene-redo">Повторить</button></div><button class="pbtn" id="scene-help">Справка и управление</button></section>')}
 else if(studio.inspector==='layers'){const names={roads:'Дороги и мосты',water:'Вода',buildings:'Здания и стены',nature:'Деревья',props:'Предметы и мебель',labels:'Подписи',shadows:'Тени'};p.innerHTML='<section><p class="ptitle">Слои карты</p><p class="pdesc">Скрытые объекты не выбираются. Видимость сохраняется в проекте и учитывается в PNG.</p>'+Object.entries(names).map(([k,n])=>`<label class="check layerRow"><input type="checkbox" data-layer="${k}"${layerVisible(k)?' checked':''}><span>${n}</span><span class="layerCount">${({roads:state.roads.length,water:state.rivers.length+(state.waterOps.length?1:0),buildings:state.buildings.length+state.walls.length,nature:state.trees.length,props:state.stamps.length,labels:state.labels.length})[k]??'—'}</span></label>`).join('')+'</section><section><button class="pbtn" id="layers-all">Показать всё</button><p class="smallnote">Это видимость, а не удаление. Геометрия воды, препятствия и автоматические связи остаются на карте.</p></section>'}
 else{sections.forEach(s=>{if(s===mapSec||s===exportSec)s.remove()});const first=p.querySelector('section');
  if(!o&&tool==='stamp'){first.innerHTML=`<p class="ptitle">${esc(STAMPS[opts.stamp].n)}</p><p class="pdesc">Выбери предмет слева и нажми на карту. Поворот и размер применятся к новым объектам.</p>`+field('o-stampS','Размер',.5,3,opts.stampS,.1,'×')+field('o-placeRot','Поворот',-180,180,opts.placeRot||0,1,'°')+`<label class="check"><input type="checkbox" id="scatter-enabled"${opts.scatterEnabled?' checked':''}> Россыпь кистью</label><label class="check"><input type="checkbox" id="scatter-random"${opts.randomAngle?' checked':''}> Случайный поворот</label>`+field('o-scatterR','Радиус россыпи',15,140,opts.scatterR)+field('o-scatterGap','Расстояние',10,80,opts.scatterGap)+`<p class="smallnote">Россыпь обходит дома, деревья, дороги и воду. Для причала или кувшинок используй одиночную постановку.</p>`}
  if(!o&&tool==='ground')first.querySelector('.grid3')?.closest('.field')?.remove();
  if((!o&&tool==='road')||(o&&sel.k==='roads')){first.querySelector('.seg')?.closest('.field')?.remove();first.insertAdjacentHTML('beforeend',selectField(o?'studio-road-selected':'studio-road','Покрытие',Object.entries(ROADMATS).map(([k,v])=>[k,v.n]),o?(o.mat||(o.paved?'cobble':'dirt')):opts.roadMat))}
  if((!o&&['tree','forest'].includes(tool))||(o&&sel.k==='trees'))first.insertAdjacentHTML('beforeend',selectField(o?'studio-tree-selected':'studio-tree','Вид дерева',[['oak','Дуб'],['pine','Ель'],['willow','Ива'],['dead','Сухое дерево']],o?o.type||'oak':opts.treeType));
  if((!o&&tool==='wall')||(o&&sel.k==='walls'))first.insertAdjacentHTML('beforeend',selectField(o?'studio-wall-selected':'studio-wall','Конструкция',[['stone','Каменная стена'],['fence','Деревянный забор'],['ruined','Разрушенная стена']],o?o.style||'stone':opts.wallStyle));
  if(!o&&tool==='select')first.insertAdjacentHTML('beforeend','<div class="studioCallout"><b>Мастерская миров</b><p>Библиотека слева: дороги, рельеф, дома и детали. Настрой погоду во вкладке «Сцена» или отключи слои.</p><button class="pbtn" id="studio-measure">Измерить расстояние · I</button></div>');
  if(!o&&tool==='measure')first.insertAdjacentHTML('beforeend','<button class="pbtn" id="measure-clear">Убрать измерение</button>');
 }
 p.insertAdjacentHTML('afterbegin',`<div class="inspectorTabs" role="tablist" aria-label="Настройки редактора">${[['properties','Свойства'],['layers','Слои'],['scene','Сцена']].map(([id,n])=>`<button role="tab" aria-selected="${studio.inspector===id}" class="${studio.inspector===id?'on':''}" data-inspector="${id}">${n}</button>`).join('')}</div>`);syncStudio()
};
$('panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.inspector){studio.inspector=b.dataset.inspector;renderPanel()}if(b.id==='layers-all'){state.layers={};sel=null;invalidate(true);commit();renderPanel()}if(b.id==='studio-measure'){setTool('measure')}if(b.id==='measure-clear')measurement=null;if(b.id==='scene-undo')undo();if(b.id==='scene-redo')redo();if(b.id==='scene-help')help.showModal()});
$('panel').addEventListener('change',e=>{const el=e.target,o=findSel(),id=el.id;if(el.dataset.layer){state.layers={...state.layers,[el.dataset.layer]:el.checked};sel=null;invalidate(true);commit();renderPanel()}
 if(id==='scene-weather'){state.weather=el.value;commit()}
 if(id==='scene-motion'){state.motion=el.checked;syncStudio();commit()}
 if(id==='scatter-enabled')opts.scatterEnabled=el.checked;if(id==='scatter-random')opts.randomAngle=el.checked;
 for(const[n,key,option]of[['road','mat','roadMat'],['tree','type','treeType'],['wall','style','wallStyle']]){if(id==='studio-'+n)opts[option]=el.value;if(id==='studio-'+n+'-selected'&&o){o[key]=el.value;invalidate(false,{S:1});commit()}}
 if(id==='scene-weatherAmount'||id==='scene-wind')commit()
});
$('panel').addEventListener('input',e=>{const el=e.target;if(el.id==='scene-weatherAmount')state.weatherAmount=+el.value;if(el.id==='scene-wind')state.wind=+el.value;const out=$(el.id+'-o');if(out&&el.id.startsWith('scene-'))out.textContent=el.value});

/* Backward-compatible files: new settings are normalized without discarding old maps. */
const validate02=validateMap;
validateMap=function(data){const s=validate02(data);s.schemaVersion=4;s.layers={};for(const k of['roads','water','buildings','nature','props','labels','shadows'])s.layers[k]=data.layers?.[k]!==false;s.weather=['clear','rain','snow','fog'].includes(data.weather)?data.weather:'clear';s.weatherAmount=Number.isFinite(data.weatherAmount)?clamp(data.weatherAmount,0,1):.45;s.wind=Number.isFinite(data.wind)?clamp(data.wind,0,1):.5;s.motion=data.motion!==false;for(const r of s.roads)r.mat=ROADMATS[r.mat]?r.mat:r.paved?'cobble':'dirt';for(const t of s.trees)t.type=['oak','pine','willow','dead'].includes(t.type)?t.type:'oak';for(const w of s.walls)w.style=['stone','fence','ruined'].includes(w.style)?w.style:'stone';return s};
// Respect the visible render stack for selection, including furniture floors.
hit=function(x,y){if(layerVisible('labels'))for(const l of [...state.labels].reverse())if(Math.abs(x-l.x)<l.text.length*l.size*.28+6&&Math.abs(y-l.y)<l.size*.6)return{k:'labels',id:l.id};
 if(layerVisible('nature'))for(const t of [...state.trees].reverse())if(dist(x,y,t.x,t.y)<t.r)return{k:'trees',id:t.id};
 if(layerVisible('props'))for(const s of [...state.stamps].reverse())if((!s.floor||state.roofMode==='interior'&&s.floor===state.level)&&dist(x,y,s.x,s.y)<STAMPS[s.type].r*s.s+2)return{k:'stamps',id:s.id};
 if(layerVisible('buildings')){if(state.roofMode==='interior')for(const w of [...state.partitions].reverse())if((w.level||1)===state.level&&polyDist(x,y,w.pts)<6)return{k:'partitions',id:w.id};for(const b of [...state.buildings].reverse())if((state.roofMode!=='interior'||(b.floors||1)>=state.level)&&inPoly(x,y,b.pts))return{k:'buildings',id:b.id}}
 for(const[k,l]of[['walls','buildings'],['roads','roads'],['rivers','water']])if(layerVisible(l))for(const o of [...state[k]].reverse())if(polyDist(x,y,sm(o))<(o.w||o.t)/2+5)return{k,id:o.id};return null
};

/* Brush batches are a single undo operation; measurement never mutates the map. */
function stampBrush(x,y){const radius=opts.scatterR,gap=opts.scatterGap,rand=rng(nextSeed());for(let i=0;i<Math.min(70,Math.ceil(radius*radius/(gap*gap)*3));i++){const a=rand()*Math.PI*2,d=Math.sqrt(rand())*radius,px=x+Math.cos(a)*d,py=y+Math.sin(a)*d,r=STAMPS[opts.stamp].r*opts.stampS;if(freeSpot(px,py,Math.max(r,gap*.6)))addStamp(opts.stamp,px,py,opts.stampS,opts.randomAngle?rand()*360:opts.placeRot||0)}invalidate(false,{S:1})}
canvas.addEventListener('pointerdown',e=>{if(spaceDown||e.button!==0||!(tool==='measure'||tool==='stamp'&&opts.scatterEnabled))return;e.stopImmediatePropagation();const p=worldPoint(e);if(p[0]<0||p[1]<0||p[0]>W||p[1]>H)return;canvas.setPointerCapture(e.pointerId);studioDrag={id:e.pointerId,last:p,kind:tool};if(tool==='measure')measurement={a:p,b:p};else stampBrush(...p)},true);
canvas.addEventListener('pointermove',e=>{if(!studioDrag||studioDrag.id!==e.pointerId)return;e.stopImmediatePropagation();const p=worldPoint(e).map((v,i)=>clamp(v,0,i?H:W));if(studioDrag.kind==='measure')measurement.b=p;else if(dist(...p,...studioDrag.last)>Math.max(8,opts.scatterR*.35)){stampBrush(...p);studioDrag.last=p}},true);
function finishStudioDrag(e){if(!studioDrag||studioDrag.id!==e.pointerId)return;e.stopImmediatePropagation();if(studioDrag.kind==='stamp')commit();studioDrag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId)}
canvas.addEventListener('pointerup',finishStudioDrag,true);canvas.addEventListener('pointercancel',finishStudioDrag,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){measurement=null;studioDrag=null}});

/* A lightweight navigation map, not a recursive full-scene render. */
function paintMinimap(){const c=$('minimap').getContext('2d'),s=312/W;c.clearRect(0,0,312,204);c.save();c.scale(s,s);c.drawImage(layA,0,0);if(layerVisible('water'))for(const r of state.rivers){tracePath(c,sm(r));c.lineWidth=r.w;c.strokeStyle='#438b9d';c.stroke()}if(layerVisible('roads'))for(const r of state.roads){tracePath(c,sm(r));c.lineWidth=r.w;c.strokeStyle='#cfb986';c.stroke()}if(layerVisible('nature'))for(const t of state.trees)circ(c,t.x,t.y,t.r,'#577448');if(layerVisible('buildings'))for(const b of state.buildings)poly(c,b.pts,b.color||'#9e7053');c.strokeStyle='#fff5cd';c.lineWidth=2/s;c.strokeRect(clamp(-view.x/view.s,0,W),clamp(-view.y/view.s,0,H),Math.min(W,cw/view.s),Math.min(H,ch/view.s));c.restore()}
$('minimap').addEventListener('pointerdown',e=>{const r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;view.x=cw/2-x*view.s;view.y=ch/2-y*view.s});

$('minimap').addEventListener('keydown',e=>{const d={ArrowLeft:[100,0],ArrowRight:[-100,0],ArrowUp:[0,100],ArrowDown:[0,-100]}[e.key];if(d){e.preventDefault();e.stopPropagation();view.x+=d[0];view.y+=d[1]}});

/* Art-directed demo details. Existing houses and road topology stay editable. */
const demo02=loadSandboxDemo;
loadSandboxDemo=function(){demo02();state.schemaVersion=4;state.weather='clear';state.motion=true;state.wind=.5;state.weatherAmount=.45;state.layers={};state.trees.forEach((t,i)=>t.type=i%11===0?'pine':i%17===0?'willow':'oak');state.roads.forEach(r=>r.mat=r.paved?'cobble':'dirt');const saved=state.roofMode;state.roofMode='roof';for(const[type,x,y,s,rot]of[['fountain',1288,767,.9,0],['windmill',380,500,1.15,-8],['waterwheel',897,560,.8,80],['sign',986,660,1,0],['woodpile',420,808,1,15],['gravestone',1790,1140,1,0],['gravestone',1820,1140,1,0],['flowerbed',1420,790,1,0],['bench',1340,785,1,0],['crystal',240,215,1,0],['torch',1140,670,1,0],['banner',1510,660,1,0]]){if(!state.buildings.some(b=>inPoly(x,y,b.pts)))addStamp(type,x,y,s,rot)}state.roofMode=saved;invalidate(true)};
loadDemo=loadSandboxDemo;
function studioReady(){$('panelToggle').onclick=()=>{if(innerWidth<=800)toggleLibrary(false);$('panel').classList.toggle('open')};renderLibrary();renderTools();renderPanel();syncStudio();if(innerWidth<=800){studio.open=false;toggleLibrary(false)}resize();fit();paintMinimap();setInterval(paintMinimap,600);help.insertAdjacentHTML('beforeend','<p>Studio 03: библиотека с поиском и избранным, слои, погода и россыпь предметов. Измерение — I. Поиск — /.</p>')}
